@Service
public class OrderService {
    public void createOrder(Order order) {
        // DRY violation: validation logic duplicated
        if (order.totalAmount() == null || order.totalAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Invalid order total");
        }
        orderRepository.save(order);
    }

    public void updateOrder(Order order) {
        // Same validation duplicated here
        if (order.totalAmount() == null || order.totalAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Invalid order total");
        }
        orderRepository.save(order);
    }

    // DRY fix: extract to single method
    private void validateOrderTotal(Order order) {
        if (order.totalAmount() == null || order.totalAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Order total must be positive");
        }
    }
}

// Over-engineered: unnecessary abstraction
public interface UserLookupStrategy {
    Optional<User> lookup(String identifier);
}

public class EmailLookupStrategy implements UserLookupStrategy {
    public Optional<User> lookup(String identifier) {
        return userRepository.findByEmail(identifier);
    }
}

public class UserService {
    private final UserLookupStrategy strategy;
    public User getUser(String email) {
        return strategy.lookup(email).orElseThrow();
    }
}

// KISS version: direct and readable
@Service
public class UserService {
    private final UserRepository userRepository;

    public User getUserByEmail(String email) {
        return userRepository.findByEmail(email)
            .orElseThrow(() -> new UserNotFoundException(email));
    }
}

// YAGNI violation: building for hypothetical future
@Service
public class NotificationService {
    // We only need email today, but building for SMS, push, webhook...
    public void send(Notification notification, Channel channel) {
        switch (channel) {
            case EMAIL -> sendEmail(notification);
            case SMS -> sendSMS(notification);      // not used yet
            case PUSH -> sendPush(notification);    // not used yet
            case WEBHOOK -> callWebhook(notification); // not used yet
        }
    }
}

// YAGNI fix: build only what is needed now
@Service
public class NotificationService {
    private final EmailSender emailSender;

    public void sendEmail(String to, String subject, String body) {
        emailSender.send(to, subject, body);
    }
    // Add sendSMS when we actually need it
}

// Accidental similarity: both format strings, but for different purposes
public class ReportService {
    public String formatCustomerName(Customer c) {
        return c.firstName() + " " + c.lastName();
    }
}

public class EmailService {
    public String formatRecipientName(User u) {
        return u.firstName() + " " + u.lastName();
    }
}

// Over-abstracted DRY: forced into shared utility
public class NameFormatter {
    public static String format(String first, String last) {
        return first + " " + last;
    }
}

